package com.pathstudy.assessment.domain;
import com.pathstudy.curriculum.domain.*; import jakarta.persistence.*; import lombok.*; import java.time.LocalDateTime;
@Entity @Table(name="assessment_versions",uniqueConstraints=@UniqueConstraint(name="uk_assessment_version_definition_revision",columnNames={"assessment_definition_id","revision_no"}),indexes={@Index(name="idx_assessment_version_definition",columnList="assessment_definition_id"),@Index(name="idx_assessment_version_curriculum",columnList="curriculum_version_id")}) @Getter @Setter @NoArgsConstructor public class AssessmentVersion extends AuditedEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="assessment_definition_id",nullable=false) private AssessmentDefinition assessmentDefinition; @Column(name="revision_no",nullable=false) private int revisionNo; @Enumerated(EnumType.STRING) @Column(nullable=false,length=16) private VersionStatus status=VersionStatus.DRAFT; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="curriculum_version_id") private CurriculumVersion curriculumVersion; private Integer targetGrade; @Column(length=4000) private String instructions; private Integer timeLimitSeconds; private LocalDateTime publishedAt; }
